	if s == "" {
		s = "/"
	}
	return s
}

func tmpRandPath(rnd *rand.Rand) string {
	segs := rnd.Intn(4) + 1
	var b strings.Builder
	for i := 0; i < segs; i++ {
		switch rnd.Intn(5) {
		case 0:
			b.WriteString("/a")
