	if s == "" {
		s = "/"
	}
	return s
}

func TestTmpFuzz(t *testing.T) {
	rnd := rand.New(rand.NewSource(42))
	panics := 0
	for iter := 0; iter < 200000; iter++ {
		nRoutes := rnd.Intn(5) + 1
		routes := make([]string, 0, nRoutes)
		for i := 0; i < nRoutes; i++ {
			routes = append(routes, tmpRandRoute(rnd))
		}
		path := tmpRandPath(rnd)
		func() {
			defer func() {
				if r := recover(); r != nil {
					panics++
					if panics < 20 {
						t.Errorf("PANIC routes=%v path=%q: %v", routes, path, r)
					}
				}
			}()
			e := New()
			for _, rt := range routes {
				rt := rt
				e.GET(rt, func(c Context) error { return errors.New("H:" + rt) })
			}
			c := e.NewContext(nil, nil)
			e.Router().Find(http.MethodGet, path, c)
			h := c.Handler()
			if h == nil {
				t.Errorf("nil handler routes=%v path=%q", routes, path)
				return
			}
			err := h(c)
			if err == nil {
				return
			}
			var he *HTTPError
			if errors.As(err, &he) {
				if he.Code != 404 && he.Code != 405 {
					t.Errorf("code %d routes=%v path=%q", he.Code, routes, path)
				}
				return
			}
			if strings.HasPrefix(err.Error(), "H:") {
				return
			}
			t.Errorf("unexpected err %v routes=%v path=%q", err, routes, path)
		}()
	}
	fmt.Println("panics:", panics)
}
