var segPool = []string{"a", "b", "ab", "abc", "c", "bc", ":p", ":q", "*", ""}

func tmpRandRoute(rnd *rand.Rand) string {
	n := rnd.Intn(4) + 1
	parts := make([]string, 0, n)
	for i := 0; i < n; i++ {
		parts = append(parts, segPool[rnd.Intn(len(segPool))])
	}
	s := "/" + strings.Join(parts, "/")
	if rnd.Intn(4) == 0 {
		s += "/"
	}
	return s
}

func tmpRandPath(rnd *rand.Rand) string {
	n := rnd.Intn(5) + 1
	parts := make([]string, 0, n)
	for i := 0; i < n; i++ {
		parts = append(parts, segPool[rnd.Intn(8)])
	}
	s := "/" + strings.Join(parts, "/")
	if rnd.Intn(4) == 0 {
		s += "/"
	}
	return s
}

type tmpRes struct {
	route string // "" if 404/405
	code  int
}

func tmpRun(routes []string, path string) (res tmpRes) {
	defer func() {
		if r := recover(); r != nil {
			res = tmpRes{route: "PANIC:" + fmt.Sprint(r)}
		}
	}()
	e := New()
	handlers := map[uintptr]string{}
	for _, rt := range routes {
		rt := rt
		h := func(c Context) error { return errors.New("H:" + rt) }
		handlers[reflect.ValueOf(h).Pointer()] = rt
		e.GET(rt, h)
	}
	c := e.NewContext(nil, nil)
	e.Router().Find(http.MethodGet, path, c)
	hh := c.Handler()
	if hh == nil {
		return tmpRes{route: "NILHANDLER"}
	}
	if rt, ok := handlers[reflect.ValueOf(hh).Pointer()]; ok {
		return tmpRes{route: rt}
	}
	err := hh(c)
	if err == nil {
		return tmpRes{route: "NOHANDLER"}
	}
	var he *HTTPError
	if errors.As(err, &he) {
		return tmpRes{code: he.Code}
	}
	return tmpRes{route: "ERR:" + err.Error()}
}

func TestTmpDiff(t *testing.T) {
	rnd := rand.New(rand.NewSource(11))
	viol := 0
	for iter := 0; iter < 100000; iter++ {
		nRoutes := rnd.Intn(4) + 1
		routes := make([]string, 0, nRoutes)
		for i := 0; i < nRoutes; i++ {
			routes = append(routes, tmpRandRoute(rnd))
		}
		path := tmpRandPath(rnd)
		full := tmpRun(routes, path)
		// single route matches?
		single := map[string]tmpRes{}
		for _, rt := range routes {
			single[rt] = tmpRun([]string{rt}, path)
		}
		if full.route == "PANIC" || strings.HasPrefix(full.route, "PANIC:") {
			viol++
			if viol < 15 {
				t.Errorf("PANIC routes=%v path=%q: %s", routes, path, full.route)
			}
			continue
		}
		if full.route != "" && !strings.HasPrefix(full.route, "NIL") && !strings.HasPrefix(full.route, "NO") {
			if single[full.route].route != full.route {
				viol++
				if viol < 15 {
					t.Errorf("WRONG MATCH routes=%v path=%q matched=%q but alone=%+v", routes, path, full.route, single[full.route])
				}
			}
		}
		if full.code == 404 {
			for _, rt := range routes {
				if single[rt].route == rt {
					viol++
					if viol < 15 {
						t.Errorf("MISSED routes=%v path=%q route %q alone matches", routes, path, rt)
					}
					break
				}
			}
		}
	}
	fmt.Println("violations:", viol)
}
