var segPool = []string{"a", "b", "ab", "abc", "c", "bc", ":p", ":q", "*", ""}

func tmpRandRoute(rnd *rand.Rand) string {
	n := rnd.Intn(4) + 1
	parts := make([]string, 0, n)
	for i := 0; i < n; i++ {
		parts = append(parts, segPool[rnd.Intn(len(segPool))])
	}
	s := "/" + strings.Join(parts, "/")
	if rnd.Intn(4) == 0 {
		s += "/"
	}
	return s
}

func tmpRandPath(rnd *rand.Rand) string {
	n := rnd.Intn(5) + 1
	parts := make([]string, 0, n)
	for i := 0; i < n; i++ {
		parts = append(parts, segPool[rnd.Intn(8)])
	}
	s := "/" + strings.Join(parts, "/")
	if rnd.Intn(4) == 0 {
		s += "/"
	}
	return s
}

// returns matched route ("" if none), http code (0 if a route handler matched), panic string
func tmpRun(routes []string, path string) (matched string, code int, panicStr string) {
	defer func() {
		if r := recover(); r != nil {
			panicStr = fmt.Sprint(r)
		}
	}()
	e := New()
	for _, rt := range routes {
		rt := rt
		e.GET(rt, func(c Context) error { return errors.New("H:" + rt) })
	}
	c := e.NewContext(nil, nil)
	e.Router().Find(http.MethodGet, path, c)
	hh := c.Handler()
	if hh == nil {
		return "NILHANDLER", 0, ""
	}
	err := hh(c)
	if err == nil {
		return "NOHANDLER", 0, ""
	}
	var he *HTTPError
	if errors.As(err, &he) {
		return "", he.Code, ""
	}
	if strings.HasPrefix(err.Error(), "H:") {
		return err.Error()[2:], 0, ""
	}
	return "ERR:" + err.Error(), 0, ""
}

func TestTmpDiff2(t *testing.T) {
	rnd := rand.New(rand.NewSource(11))
	viol := 0
	for iter := 0; iter < 100000; iter++ {
		nRoutes := rnd.Intn(4) + 1
		routes := make([]string, 0, nRoutes)
		for i := 0; i < nRoutes; i++ {
			routes = append(routes, tmpRandRoute(rnd))
		}
		path := tmpRandPath(rnd)
		full, code, pstr := tmpRun(routes, path)
		if pstr != "" {
			viol++
			if viol < 15 {
				t.Errorf("PANIC routes=%v path=%q: %s", routes, path, pstr)
			}
			continue
		}
		if full != "" && full != "NILHANDLER" && full != "NOHANDLER" && !strings.HasPrefix(full, "ERR:") {
			alone, _, _ := tmpRun([]string{full}, path)
			if alone != full {
				viol++
				if viol < 15 {
					t.Errorf("WRONG MATCH routes=%v path=%q matched=%q but alone=%q", routes, path, full, alone)
				}
			}
		}
		if code == 404 {
			for _, rt := range routes {
				alone, _, _ := tmpRun([]string{rt}, path)
				if alone == rt {
					viol++
					if viol < 15 {
						t.Errorf("MISSED routes=%v path=%q route %q alone matches", routes, path, rt)
					}
					break
				}
			}
		}
	}
	fmt.Println("violations:", viol)
}
