341		ctx := c.(*context)
342		ctx.path = path
343		currentNode := r.tree // Current node as root
344	
345		var (
346			// search stores the remaining path to check for match. By each iteration we move from start of path to end of the path
347			// and search value gets shorter and shorter.
348			search      = path
349			searchIndex = 0
350			paramIndex  int           // Param counter
351			paramValues = ctx.pvalues // Use the internal slice so the interface can keep the illusion of a dynamic slice
352		)
353	
354		// Backtracking is needed when a dead end (leaf node) is reached in the router tree.
355		// To backtrack the current node will be changed to the parent node and the next kind for the
356		// router logic will be returned based on fromKind or kind of the dead end node (static > param > any).
357		// For example if there is no static node match we should check parent next sibling by kind (param).
358		// Backtracking itself does not check if there is a next sibling, this is done by the router logic.
359		backtrackToNextNodeKind := func(fromKind kind) (nextNodeKind kind, valid bool) {
360			previous := currentNode
361			currentNode = previous.parent
362			valid = currentNode != nil
363	
364			// Next node type by priority
365			// NOTE: With the current implementation we never backtrack from an `any` route, so `previous.kind` is
366			// always `static` or `any`
367			// If this is changed then for any route next kind would be `static` and this statement should be changed
368			nextNodeKind = previous.kind + 1
369	
370			if fromKind == staticKind {
371				// when backtracking is done from static kind block we did not change search so nothing to restore
372				return
373			}
374	
375			// restore search to value it was before we move to current node we are backtracking from.
376			if previous.kind == staticKind {
377				searchIndex -= len(previous.prefix)
378			} else {
379				paramIndex--
380				// for param/any node.prefix value is always `:` so we can not deduce searchIndex from that and must use pValue
381				// for that index as it would also contain part of path we cut off before moving into node we are backtracking from
382				searchIndex -= len(paramValues[paramIndex])
383			}
384			search = path[searchIndex:]
385			return
386		}
387	
388		// Router tree is implemented by longest common prefix array (LCP array) https://en.wikipedia.org/wiki/LCP_array
389		// Tree search is implemented as for loop where one loop iteration is divided into 3 separate blocks
390		// Each of these blocks checks specific kind of node (static/param/any). Order of blocks reflex their priority in routing.
391		// Search order/priority is: static > param > any.
392		//
393		// Note: backtracking in tree is implemented by replacing/switching currentNode to previous node
394		// and hoping to (goto statement) next block by priority to check if it is the match.
395		for {
396			prefixLen := 0 // Prefix length
397			lcpLen := 0    // LCP (longest common prefix) length
398	
399			if currentNode.kind == staticKind {
400				searchLen := len(search)
401				prefixLen = len(currentNode.prefix)
402	
403				// LCP - Longest Common Prefix (https://en.wikipedia.org/wiki/LCP_array)
404				max := prefixLen
405				if searchLen < max {
406					max = searchLen
407				}
408				for ; lcpLen < max && search[lcpLen] == currentNode.prefix[lcpLen]; lcpLen++ {
409				}
410			}
411	
412			if lcpLen != prefixLen {
413				// No matching prefix, let's backtrack to the first possible alternative node of the decision path
414				nk, ok := backtrackToNextNodeKind(staticKind)
415				if !ok {
416					return // No other possibilities on the decision path
417				} else if nk == paramKind {
418					goto Param
419					// NOTE: this case (backtracking from static node to previous any node) can not happen by current any matching logic. Any node is end of search currently
420					//} else if nk == anyKind {
421					//	goto Any
422				} else {
423					// Not found (this should never be possible for static node we are looking currently)
424					return
425				}
426			}
427	
428			// The full prefix has matched, remove the prefix from the remaining search
429			search = search[lcpLen:]
430			searchIndex = searchIndex + lcpLen
431	
432			// Finish routing if no remaining search and we are on an leaf node
433			if search == "" && currentNode.ppath != "" {
434				break
435			}
436	
437			// Static node
438			if search != "" {
439				if child := currentNode.findStaticChild(search[0]); child != nil {
440					currentNode = child
441					continue
442				}
443			}
444	
445		Param:
446			// Param node
447			if child := currentNode.paramChild; search != "" && child != nil {
448				currentNode = child
449				// FIXME: when param node does not have any children then param node should act similarly to any node - consider all remaining search as match
