package echo

import (
	"errors"
	"fmt"
	"math/rand"
	"net/http"
	"strings"
	"testing"
)

// ---- reference structural matcher (echo semantics) ----
func refMatch(pattern, path string) bool {
	ps := strings.Split(pattern, "/")
	xs := strings.Split(path, "/")
	for len(ps) > 0 {
		p := ps[0]
		if p == "*" {
			return len(xs) >= 1
		}
		if len(xs) == 0 {
			return false
		}
		switch {
		case p == "":
			if xs[0] != "" {
				return false
			}
		case p[0] == ':':
			if xs[0] == "" {
				return false
			}
		default:
			if p != xs[0] {
				return false
			}
		}
		ps, xs = ps[1:], xs[1:]
	}
	return len(xs) == 0
}

var statics = []string{"a", "b", "ab", "abc", "c", "bc", "x", "users", "files"}

func randRoute(rnd *rand.Rand) string {
	n := rnd.Intn(4) + 1
	parts := make([]string, 0, n)
	for i := 0; i < n; i++ {
		switch rnd.Intn(5) {
		case 0:
			parts = append(parts, ":"+string(rune('a'+rnd.Intn(3))))
		case 1:
			if i == n-1 {
				parts = append(parts, "*")
			} else {
				parts = append(parts, statics[rnd.Intn(len(statics))])
			}
		default:
			parts = append(parts, statics[rnd.Intn(len(statics))])
		}
	}
	return "/" + strings.Join(parts, "/")
}

func randPath(rnd *rand.Rand) string {
	n := rnd.Intn(5) + 1
	parts := make([]string, 0, n)
	for i := 0; i < n; i++ {
		parts = append(parts, statics[rnd.Intn(len(statics))])
	}
	return "/" + strings.Join(parts, "/")
}

type res struct {
	matched string
	code    int
	panicS  string
}

func run(routes []string, path string) (r res) {
	defer func() {
		if rec := recover(); rec != nil {
			r = res{panicS: fmt.Sprint(rec)}
		}
	}()
	e := New()
	for _, rt := range routes {
		rt := rt
		e.GET(rt, func(c Context) error { return errors.New("H:" + rt) })
	}
	c := e.NewContext(nil, nil)
	e.Router().Find(http.MethodGet, path, c)
	h := c.Handler()
	if h == nil {
		return res{matched: "NIL"}
	}
	err := h(c)
	if err == nil {
		return res{matched: "NOHANDLER"}
	}
	var he *HTTPError
	if errors.As(err, &he) {
		return res{code: he.Code}
	}
	if strings.HasPrefix(err.Error(), "H:") {
		return res{matched: err.Error()[2:]}
	}
	return res{matched: "ERR:" + err.Error()}
}

func TestTmpRef(t *testing.T) {
	rnd := rand.New(rand.NewSource(1234))
	viol := 0
	for iter := 0; iter < 300000; iter++ {
		nRoutes := rnd.Intn(4) + 1
		routes := make([]string, 0, nRoutes)
		for i := 0; i < nRoutes; i++ {
			routes = append(routes, randRoute(rnd))
		}
		path := randPath(rnd)
		got := run(routes, path)
		if got.panicS != "" {
			viol++
			if viol < 10 {
				t.Errorf("PANIC routes=%v path=%q: %s", routes, path, got.panicS)
			}
			continue
		}
		anyMatch := false
		for _, rt := range routes {
			if refMatch(rt, path) {
				anyMatch = true
				break
			}
		}
		if got.matched != "" && !strings.HasPrefix(got.matched, "NIL") && !strings.HasPrefix(got.matched, "NO") && !strings.HasPrefix(got.matched, "ERR:") {
			if !refMatch(got.matched, path) {
				viol++
				if viol < 10 {
					t.Errorf("FALSE MATCH routes=%v path=%q matched=%q", routes, path, got.matched)
				}
			}
		}
		if got.code == 404 && anyMatch {
			viol++
			if viol < 10 {
				t.Errorf("MISSED 404 routes=%v path=%q", routes, path)
			}
		}
		if got.code == 405 && !anyMatch {
			viol++
			if viol < 10 {
				t.Errorf("WRONG 405 routes=%v path=%q", routes, path)
			}
		}
	}
	fmt.Println("violations:", viol)
}
EOF
