		if wantCE {
			if ce != gzipScheme {
				t.Fatalf("%s: expected CE gzip, got %q", path, ce)
			}
			r, err := gzip.NewReader(bytes.NewReader(raw))
			if err != nil {
				t.Fatalf("%s: gzip.NewReader: %v", path, err)
			}
			dec, err := ioutil.ReadAll(r)
			r.Close()
			if err != nil {
				t.Fatalf("%s: read: %v", path, err)
			}
			if string(dec) != wantBody {
				t.Fatalf("%s: decoded %q want %q", path, dec, wantBody)
			}
