package echo

import (
	"errors"
	"fmt"
	"math/rand"
	"sort"
	"strings"
	"testing"
)

var segs = []string{"a", "b", "ab", "abc", "c", "bc", "x", "y"}

func randStaticPath(rnd *rand.Rand) string {
	n := rnd.Intn(3) + 1
	parts := make([]string, 0, n)
	for i := 0; i < n; i++ {
		parts = append(parts, segs[rnd.Intn(len(segs))])
	}
	return "/" + strings.Join(parts, "/")
}

func randAnyPath(rnd *rand.Rand) string {
	n := rnd.Intn(2) + 1
	parts := make([]string, 0, n)
	for i := 0; i < n; i++ {
		parts = append(parts, segs[rnd.Intn(len(segs))])
	}
	return "/" + strings.Join(parts, "/") + "/*"
}

func randReqPath(rnd *rand.Rand) string {
	n := rnd.Intn(4) + 1
	parts := make([]string, 0, n)
	for i := 0; i < n; i++ {
		parts = append(parts, segs[rnd.Intn(len(segs))])
	}
	return "/" + strings.Join(parts, "/")
}

// reference: static exact match wins; else longest matching any-prefix; else 404
func refMatch(statics []string, anys []string, p string) string {
	for _, s := range statics {
		if s == p {
			return s
		}
	}
	best := ""
	for _, a := range anys {
		prefix := strings.TrimSuffix(a, "*") // keeps trailing "/"
		if strings.HasPrefix(p, prefix) && len(a) > len(best) {
			best = a
		}
	}
	return best
}

func TestTmpFuzzStaticAny(t *testing.T) {
	rnd := rand.New(rand.NewSource(7))
	bad := 0
	for iter := 0; iter < 20000; iter++ {
		nStatic := rnd.Intn(4)
		nAny := rnd.Intn(3)
		if nStatic+nAny == 0 {
			continue
		}
		var statics, anys []string
		seen := map[string]bool{}
		for i := 0; i < nStatic; i++ {
			p := randStaticPath(rnd)
			if !seen[p] {
				seen[p] = true
				statics = append(statics, p)
			}
		}
		for i := 0; i < nAny; i++ {
			p := randAnyPath(rnd)
			if !seen[p] {
				seen[p] = true
				anys = append(anys, p)
			}
		}
		e := New()
		// register in random order
		type reg struct {
			p string
			a bool
		}
		var regs []reg
		for _, p := range statics {
			regs = append(regs, reg{p, false})
		}
		for _, p := range anys {
			regs = append(regs, reg{p, true})
		}
		rnd.Shuffle(len(regs), func(i, j int) { regs[i], regs[j] = regs[j], regs[i] })
		for _, r := range regs {
			r := r
			e.GET(r.p, func(c Context) error { return errors.New("H:" + r.p) })
		}
		for k := 0; k < 8; k++ {
			p := randReqPath(rnd)
			want := refMatch(statics, anys, p)
			got := ""
			c := e.NewContext(nil, nil)
			e.Router().Find("GET", p, c)
			if h := c.Handler(); h != nil {
				if err := h(c); err != nil {
					s := err.Error()
					if strings.HasPrefix(s, "H:") {
						got = s[2:]
					}
				}
			}
			if got != want {
				bad++
				if bad < 10 {
					sort.Strings(statics)
					sort.Strings(anys)
					t.Errorf("MISMATCH statics=%v anys=%v req=%q got=%q want=%q", statics, anys, p, got, want)
				}
			}
		}
	}
	fmt.Println("mismatches:", bad)
}
