package echo

import (
	"errors"
	"fmt"
	"net/http"
	"strings"
	"testing"
)

func refMatch(pattern, path string) bool {
	ps := strings.Split(pattern, "/")
	xs := strings.Split(path, "/")
	for len(ps) > 0 {
		p := ps[0]
		if p == "*" {
			return len(xs) >= 1
		}
		if len(xs) == 0 {
			return false
		}
		switch {
		case p == "":
			if xs[0] != "" {
				return false
			}
		case p[0] == ':':
			if xs[0] == "" {
				return false
			}
		default:
			if p != xs[0] {
				return false
			}
		}
		ps, xs = ps[1:], xs[1:]
	}
	return len(xs) == 0
}

type res struct {
	matched string
	code    int
	panicS  string
}

func run(routes []string, path string) (r res) {
	defer func() {
		if rec := recover(); rec != nil {
			r = res{panicS: fmt.Sprint(rec)}
		}
	}()
	e := New()
	for _, rt := range routes {
		rt := rt
		e.GET(rt, func(c Context) error { return errors.New("H:" + rt) })
	}
	c := e.NewContext(nil, nil)
	e.Router().Find(http.MethodGet, path, c)
	h := c.Handler()
	if h == nil {
		return res{matched: "NIL"}
	}
	err := h(c)
	if err == nil {
		return res{matched: "NOHANDLER"}
	}
	var he *HTTPError
	if errors.As(err, &he) {
		return res{code: he.Code}
	}
	if strings.HasPrefix(err.Error(), "H:") {
		return res{matched: err.Error()[2:]}
	}
	return res{matched: "ERR:" + err.Error()}
}

func genPatterns(maxSegs int, alphabet []string) []string {
	var out []string
	var rec func(segs []string, depth int)
	rec = func(segs []string, depth int) {
		if len(segs) > 0 {
			out = append(out, "/"+strings.Join(segs, "/"))
		}
		if depth == maxSegs {
			return
		}
		for _, a := range alphabet {
			rec(append(segs, a), depth+1)
		}
	}
	rec(nil, 0)
	return out
}

func genPaths(maxSegs int, alphabet []string) []string {
	var out []string
	var rec func(segs []string, depth int)
	rec = func(segs []string, depth int) {
		if len(segs) > 0 {
			out = append(out, "/"+strings.Join(segs, "/"))
		}
		if depth == maxSegs {
			return
		}
		for _, a := range alphabet {
			rec(append(segs, a), depth+1)
		}
	}
	rec(nil, 0)
	return out
}

func TestTmpExhaustive(t *testing.T) {
	patterns := genPatterns(2, []string{"a", "b", ":p", "*", ""})
	paths := genPaths(4, []string{"a", "b", "x", ""})
	fmt.Println("patterns:", len(patterns), "paths:", len(paths))
	viol := 0
	check := func(routes []string, path string) {
		got := run(routes, path)
		if got.panicS != "" {
			viol++
			if viol < 10 {
				t.Errorf("PANIC routes=%v path=%q: %s", routes, path, got.panicS)
			}
			return
		}
		anyMatch := false
		for _, rt := range routes {
			if refMatch(rt, path) {
				anyMatch = true
				break
			}
		}
		if got.matched != "" && !strings.HasPrefix(got.matched, "NIL") && !strings.HasPrefix(got.matched, "NO") && !strings.HasPrefix(got.matched, "ERR:") {
			if !refMatch(got.matched, path) {
				viol++
				if viol < 10 {
					t.Errorf("FALSE MATCH routes=%v path=%q matched=%q", routes, path, got.matched)
				}
			}
		}
		if got.code == 404 && anyMatch {
			viol++
			if viol < 10 {
				t.Errorf("MISSED 404 routes=%v path=%q", routes, path)
			}
		}
		if got.code == 405 && !anyMatch {
			viol++
			if viol < 10 {
				t.Errorf("WRONG 405 routes=%v path=%q", routes, path)
			}
		}
	}
	for i := range patterns {
		for _, p := range paths {
			check([]string{patterns[i]}, p)
		}
		for j := i; j < len(patterns); j++ {
			for _, p := range paths {
				check([]string{patterns[i], patterns[j]}, p)
			}
		}
	}
	fmt.Println("violations:", viol)
}
